sourceSnapshot.family_exposure.py:
"""Separate manual-chart exposure and source-style early stopping.

The weak corpus is FIXED in every condition and disjoint from all six manual
song groups. Compare training on all six manual charts with leave-one-manual
training, at one prespecified historical-style configuration. This diagnostic
does not select a release model or claim the archive's exact training batch.
"""
from family_train import *
from family import classify,smooth
from analyse import score_segments
import concurrent.futures,argparse,subprocess

CONFIG={'localL2':.0005,'strongWeight':1.,'balance':'cap6'}
SPEC={'recipe':'count_primary','representation':'original'}
_MAIN=_MANUAL=_META=_ROOT=None

def init(root):
    global _MAIN,_MANUAL,_META,_ROOT
    _MAIN,_MANUAL,_=load();_META=load_metadata();_ROOT=Path(root)

def source_gd(weak,strong,family):
    data=HeadData(weak,strong,_META,family,'original','count_primary',CONFIG)
    W=torch.nn.Parameter(torch.zeros(len(data.classes),data.x.shape[1]));b=torch.nn.Parameter(torch.zeros(len(data.classes)))
    for epoch in range(500):
        W.grad=b.grad=None;loss=data.objective(W,b,CONFIG);loss.backward()
        with torch.no_grad():W-=.08*W.grad;b-=.08*b.grad
    W.grad=b.grad=None;loss=data.objective(W,b,CONFIG);loss.backward()
    fitted={'classes':data.classes,'keys':SCHEMA['original'],'mean':data.mean.tolist(),'std':data.std.tolist(),
      'W':W.detach().numpy().ravel().tolist(),'b':b.detach().numpy().tolist()}
    trace={'policy':'prespecified source-style GD500/lr.08','epochs':500,'loss':float(loss.detach()),
      'gradientMax':max(float(W.grad.abs().max()),float(b.grad.abs().max())),**data.scope}
    return fitted,trace

def job(task):
    optimizer,held=task;strong=_MANUAL if held<0 else[r for i,r in enumerate(_MANUAL)if i!=held]
    path=_ROOT/'models'/(optimizer+'-'+('full'if held<0 else str(held))+'.json');train_uids=[r['uid']for r in _MAIN+strong]
    if path.exists():
        saved=json.loads(path.read_text(encoding='utf8'));models,trace=saved['models'],saved['fit']
        if saved['trainUids']!=train_uids:raise RuntimeError('Exposure diagnostic scope changed')
    else:
        models={};trace={}
        if optimizer=='converged':models,trace=fit_pair(_MAIN,strong,_META,SPEC,CONFIG)
        else:
            for family in ['rc','ln']:models[family],trace[family]=source_gd(_MAIN,strong,family)
        dump(path,{'models':models,'fit':trace,'trainUids':train_uids,'weakCorpusFixed':True,'config':CONFIG})
    evaluation=_MANUAL if held<0 else[_MANUAL[held]];rows=[]
    for r in evaluation:
        raw=classify(r,_META[r['uid']],models,'original',.45,'model')
        rows.extend({'uid':r['uid'],**s}for s in smooth(raw))
    return {'optimizer':optimizer,'held':held,'segments':rows,'fit':trace,'metrics':score_segments(evaluation,rows)}

def run(args):
    main,manual,_=load();root=Path(args.output)
    if {r['group']for r in main}&{r['group']for r in manual}:raise RuntimeError('Weak/manual song overlap')
    protocol={'id':'manual-exposure-early-stop-r1','config':CONFIG,'spec':SPEC,
      'sourceBaseCommit':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),
      'sourceSnapshot':{n:(Path(__file__).parent/n).read_text(encoding='utf8')for n in ['family_exposure.py','family.py','family_train.py']},
      'weakUidsFixedInAllConditions':[r['uid']for r in main],'manualUids':[r['uid']for r in manual],
      'scope':'retrospective diagnostic; fixed weak training corpus; full-manual resubstitution versus leave-one-manual accuracy; fixed original boundaries and historical-style config, no hyperparameter selection',
      'policies':['GD500/lr.08 at recorded source-style settings','same scalar objective optimized with the family convergence policy'],
      'archive':'nearby historical source recipe, not a verified reconstruction of the archived training batch'}
    p=root/'protocol.json'
    if p.exists()and json.loads(p.read_text(encoding='utf8'))!=protocol:raise RuntimeError('Exposure protocol changed; use a new revision')
    dump(p,protocol)
    with concurrent.futures.ProcessPoolExecutor(max_workers=args.workers,initializer=init,initargs=(str(root),))as pool:
        results=list(pool.map(job,[(policy,held)for policy in ['gd500','converged']for held in range(-1,6)]))
    metrics={};segments=[]
    for policy in ['gd500','converged']:
        full=next(r for r in results if r['optimizer']==policy and r['held']==-1)
        loo=[s for r in results if r['optimizer']==policy and r['held']>=0 for s in r['segments']]
        metrics[policy]={'fullManualResubstitution':full['metrics'],'leaveOneManual':score_segments(manual,loo)}
        segments.extend({'policy':policy,'condition':'full',**s}for s in full['segments'])
        segments.extend({'policy':policy,'condition':'leave_one',**s}for s in loo)
    rng=np.random.default_rng(20261031);draw=rng.multinomial(6,np.full(6,1/6),size=2000)/6
    a=np.array([r['accuracy']for r in metrics['gd500']['leaveOneManual']['charts']]);b=np.array([r['accuracy']for r in metrics['converged']['leaveOneManual']['charts']])
    delta={'convergedMinusGd500':float((b-a).mean()),'pairedChart95':np.quantile(draw@(b-a),[.025,.975]).tolist()}
    dump(root/'metrics.json',{'scope':protocol['scope'],'metrics':metrics,'optimizerEffect':delta})
    dump(root/'segments.json',segments);dump(root/'fits.json',[{k:v for k,v in r.items()if k!='segments'}for r in results])
    lines=['# 固定弱训练集，分开人工谱暴露与训练停止策略','',
      '同一批弱整谱、同一原结构/边界及同一预定历史式配置。全六谱列是训练集重代入，留一列的该张人工谱未参与拟合；不以此诊断选择发布参数。',
      '', '| 优化策略 | 全六谱重代入 | 留一人工谱 |','|---|---:|---:|']
    for policy,m in metrics.items():lines.append(f"| {policy} | {m['fullManualResubstitution']['chartMeanAccuracy']:.2%} | {m['leaveOneManual']['chartMeanAccuracy']:.2%} |")
    lines+=['',f"留一时，充分优化减 GD500 的分段差值为 {100*delta['convergedMinusGd500']:+.2f} 个百分点，六谱成对区间为 [{100*delta['pairedChart95'][0]:+.2f}, {100*delta['pairedChart95'][1]:+.2f}]。",
      '', '附近历史源码采用 500 轮、学习率 0.08；归档精确训练批次仍未定位。结果解释当前数据上的暴露和优化策略效应，不将历史源码的相似性当作归档训练身份。完整模型、实际输出和训练梯度见本目录。']
    (root/'REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
    dump(root/'complete.json',{'conditions':14,'headFits':28,'hyperparameterSelections':0})
    print('\n'.join(lines),flush=True)

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--workers',type=int,default=3);p.add_argument('--output',default='research/rework/results/family-exposure-r1');run(p.parse_args())

sourceSnapshot.family.py:
"""The archived hierarchical expert/gating decision, with replaceable heads.

Unlike the flat 16-way representation comparator, this preserves the original
RC/LN route, rule exceptions and Break heuristics. Cold refits can then compare
the actual original architecture without inheriting frozen pretrained weights.
"""
from mil import *

def load_metadata():
    with Path('.cache/rework-family-meta.jsonl').open(encoding='utf8')as f:
        return {r['uid']:r for r in map(json.loads,f)}

def model_scores(model,x):
    z=(x-np.array(model['mean']))/np.array(model['std'])@np.array(model['W']).reshape(len(model['classes']),-1).T+np.array(model['b'])
    z-=z.max(1,keepdims=True);p=np.exp(z);return p/p.sum(1,keepdims=True)

def classify(record,metadata,models,representation='original',ln_ratio=.45,scorer='model',precomputed=None):
    segments=record['segments'];meta=metadata[representation]
    if scorer!='rules':
        if precomputed is None:
            x=np.array([s[representation]for s in segments]);rc=model_scores(models['rc'],x);ln=model_scores(models['ln'],x)
        else:rc,ln=precomputed['rc'],precomputed['ln']
    features=[m['gates']for m in meta];nps=sorted(g['nps']for g in features if g['rowCount'])
    map_nps=nps[len(nps)//2]if nps else 0.;all_nps=sorted(g['nps']for g in features);median_nps=all_nps[len(all_nps)//2]
    output=[];burdens=[]
    for i,(segment,m,g)in enumerate(zip(segments,meta,features)):
        row={'start':segment['start'],'end':segment['end']};duration=row['end']-row['start']
        burden=g['nps']*(.5+g['chordMean']/3)*(.6+g['jackSpeedBpm']/150);row['burden']=burden
        low=(duration>=2500 and g['nps']<map_nps and
             (g['nps']<18.5 and g['segIvLogStd']>.41 or
              g['chordMean']<1.9 and g['vibroFraction']>.3 and g['segRhythmChangeRate']<.1 or
              g['nps']<22.5 and g['segIvLogStd']>.25 and g['vibroFraction']<.45 and g['lnWeightRatio']<.5))
        if m['family0']=='break'or not g['rowCount']or low:
            row.update(tag='break',family='break',confidence=1.)
        else:
            family='ln'if(g['lnWeightRatio']>=ln_ratio or g['lockRatio']>=.5 and g['heldCoverage']>=.15 and g['lnWeightRatio']>=.2)else'rc'
            rule=m['ruleLn'if family=='ln'else'ruleRc']
            if scorer=='rules':scores=dict(rule)
            else:
                head=models[family];mdl=dict(zip(head['classes'],ln[i]if family=='ln'else rc[i]))
                scores={}
                for tag in dict.fromkeys(list(mdl)+list(rule)):
                    if tag=='vibro':scores[tag]=min(1.,rule.get(tag,0)*2)
                    elif tag in ['wildcard','ln wildcard']:scores[tag]=rule.get(tag,0)*.6
                    elif scorer=='model':scores[tag]=mdl.get(tag,0)*1.4
                    else:scores[tag]=.5*(mdl.get(tag,0)+rule.get(tag,0))
            # Pure rules can have ZERO affinity after the LN lock rescue route:
            # its old lnPresence factor still gates every class at lnWeight=.45.
            # Zero information is not evidence for the dictionary's first tag.
            if sum(scores.values())<=0:
                unknown='ln wildcard'if family=='ln'else'wildcard'
                row.update(tag=unknown,family=family,confidence=0.,scores={unknown:1.},secondary=None,evidenceState='zero-rule-abstention')
                burdens.append(burden);output.append(row);continue
            ranked=sorted(scores.items(),key=lambda pair:-pair[1]);tag,confidence=ranked[0]
            if tag in ['wildcard','ln wildcard']:
                for other,value in ranked[1:]:
                    if other not in ['wildcard','ln wildcard']and value>.3:tag,confidence=other,value;break
            secondary=ranked[1][0]if len(ranked)>1 and ranked[1][1]>=ranked[0][1]*.75 and ranked[1][1]>.3 else None
            row.update(tag=tag,family=family,confidence=min(1.,float(confidence)),scores=scores,secondary=secondary)
        burdens.append(math.inf if row['family']=='break'else burden);output.append(row)
    finite=sorted(v for v in burdens if math.isfinite(v));p15=finite[int(len(finite)*.15)]if finite else math.inf
    for row,g,burden in zip(output,features,burdens):
        if row['family']=='break':continue
        easy=(row['confidence']<.5 and burden<=max(p15,1)and g['nps']<map_nps)
        sparse=(row['end']-row['start']<20000 and g['nps']>0 and g['nps']<median_nps*.4 and g['nps']<4)
        if easy or sparse:row.update(tag='break',family='break',secondary=None)
    for row in output:
        if row['family']=='break':row['probability']=[float(c=='break')for c in CLASSES]
        else:
            scores=row['scores'].copy();top=max(scores,key=scores.get)
            if top in ['wildcard','ln wildcard']and row['tag']not in ['wildcard','ln wildcard']:
                scores['wildcard']=0.;scores['ln wildcard']=0.
            total=sum(scores.values());row['probability']=[float(scores.get(c,0)/total)for c in CLASSES]
    return output

def smooth(rows,min_segment=3000):
    # Exact historical policy, including first-segment evidence inheritance.
    rows=[r.copy()for r in rows];out=[];minimum=.6*min_segment
    for row in rows:
        last=out[-1]if out else None
        if last and all(last.get(k)==row.get(k)for k in ['tag','secondary','family'])and row['end']-row['start']<minimum:last['end']=row['end']
        else:out.append(row)
    result=[]
    for i,row in enumerate(out):
        previous=result[-1]if result else None;following=out[i+1]if i+1<len(out)else None
        if row['family']=='break'and row['end']-row['start']<minimum and previous and following and following['tag']==previous['tag']:previous['end']=row['end']
        else:result.append(row)
    return result

def check_archived_consumer():
    main,manual,data=load();metadata=load_metadata();models=json.loads(Path('.cache/archived-model-reference.json').read_text(encoding='utf8'))
    original={r['uid']:r for r in json.loads(Path('.cache/rework-legacy-full.json').read_text(encoding='utf8'))}
    n=0
    for r in data:
        prediction=classify(r,metadata[r['uid']],models)
        assert [s['tag']for s in prediction]==[s['legacy']for s in r['segments']],r['uid']+' raw tags'
        expected=original[r['uid']]['segments'];actual=smooth(prediction)
        assert len(actual)==len(expected),r['uid']+' smoothing length'
        for a,e in zip(actual,expected):
            for key in ['start','end','tag','family']:assert a[key]==e[key],r['uid']+' '+key
            assert abs(a['confidence']-e['confidence'])<1e-10,r['uid']+' confidence'
        n+=1
    print('hierarchical native consumer parity',n,'complete cached charts; no model refitting',flush=True)

if __name__=='__main__':check_archived_consumer()
